#include <stdio.h>
#include <string.h>

void permute(char *s, int start) {
    int n = strlen(s);
    if (start == n - 1) {
        printf("%s\n", s);
        return;
    }
    for (int i = start; i < n; i++) {
        char t = s[start];
        s[start] = s[i];
        s[i] = t;
        permute(s, start + 1);
        t = s[start];
        s[start] = s[i];
        s[i] = t;
    }
}

int main() {
    char word[] = "abc";
    permute(word, 0);
    return 0;
}
